/** Профиль предприятия, от которого зависит применимость требований. */
export interface NormProfile {
  objectTypes: string[];   // restaurant, cafe, canteen, catering, delivery, school, hospital
  salesModes: string[];    // hall, takeaway, delivery, catering
  seats: number | null;    // посадочных мест (null — не указано)
  features: string[];      // fryer — фритюр; outside_sales — реализация вне предприятия без услуг; social — стационарное соцобслуживание; children — питание детей
  region?: string | null;  // субъект РФ предприятия (для территориальных разъяснений)
}

export const FEATURES: Record<string, string> = {
  fryer: 'Готовим во фритюре',
  outside_sales: 'Продаём продукцию вне предприятия (магазин, отдел кулинарии, поставка) без оказания услуг питания',
  social: 'Кормим проживающих в организации социального обслуживания',
  children: 'Кормим детей в организованных детских коллективах',
  host_facility: 'Работаем в составе гостиницы, бани, спортивного или досугового объекта',
};

export interface Clause {
  id: string; doc: keyof typeof DOCS; clause: string;
  title: string;                                   // коротко, для списка
  text: string;                                    // дословно
  applies?: (p: NormProfile) => boolean;           // нет — для всех
  appliesNote?: string;                            // когда применяется (для пользователя)
  check: string | null;                            // ключ проверки по данным (checks.ts); null — проверяется на месте
}

const catering = (p: NormProfile) => p.objectTypes.includes('catering') || p.salesModes.includes('catering');
const medicalOrSocial = (p: NormProfile) => p.objectTypes.includes('hospital') || p.features.includes('social');
const children = (p: NormProfile) => p.objectTypes.includes('school') || p.features.includes('children');
const spScope = (p: NormProfile) => medicalOrSocial(p) || p.features.includes('host_facility');
const SP_NOTE = 'общепит в составе медицинской, социальной организации, гостиницы, бани, спортивного или досугового объекта (СП 2.1.4284-26, пп. 1–2)';
const offsite = (p: NormProfile) => p.features.includes('outside_sales') || p.salesModes.some((m) => ['takeaway', 'delivery', 'catering'].includes(m)) || p.objectTypes.some((t) => ['delivery', 'catering'].includes(t));

